#include <iostream>
#include <map>
#include <string>
using namespace std;

int main() {
    map<string, int> fish;
    fish["{w1}"] = {a};
    fish["{w2}"] = {b};

    int total = 0;
    for (auto p : fish) {
        total += p.second;
    }
    cout << total << endl;
    return 0;
}
